package com.bananalab.lite;
import org.json.*;import java.io.*;import java.nio.file.*;import java.util.*;
/** Host report, not a pass/fail suite: reader vs the lexical extractor on generated held-out examples.
 *  Usage: LectorHeldoutReport raiz ejemplos.json salida.json [maximo] */
public final class LectorHeldoutReport{
 static final double[] LEVELS={0,.3,.5,.7,.8,.9,.95};static int[] sharedShown=new int[7],sharedRight=new int[7],freeShown=new int[7],freeRight=new int[7];static int gateShown,gateRight,lexicalSilent,fallbackShown,fallbackRight;
 static String flat(String s){return new Lector.Flat(s,true).text.toString();}
 public static void main(String[] a)throws Exception{Path root=Paths.get(a[0]);BananaTransformer m;try(InputStream in=Files.newInputStream(root.resolve("assets/lector1/lector1.bin"))){m=BananaTransformer.container(in);}
  JSONArray examples=new JSONArray(new String(Files.readAllBytes(Paths.get(a[1])),"UTF-8"));int limit=a.length>3?Integer.parseInt(a[3]):examples.length();Map<String,int[]> by=new TreeMap<>();int n=0,neural=0,lexical=0,shownWrong=0,lexicalAnswered=0;long tokens=0,time=System.nanoTime();
  for(int i=0;i<examples.length()&&n<limit;i++){JSONArray e=examples.getJSONArray(i);String ctx=e.getString(0),q=e.getString(1),target=e.getString(2),kind=e.getString(3);if(kind.equals("negative"))continue;n++;int[] row=by.get(kind);if(row==null)by.put(kind,row=new int[3]);row[0]++;
   boolean passed=false,passedRight=false;Lector.Out o=Lector.answer(m,ctx,q);String found=o==null?null:Lector.ground(ctx,o.text);boolean hit=found!=null&&flat(found).equals(flat(target));if(found!=null){boolean shared=ReadingKnowledge.common(ReadingKnowledge.words(q),ReadingKnowledge.words(found))>0;for(int t=0;t<LEVELS.length;t++)if(o.confidence>=LEVELS[t]){(shared?sharedShown:freeShown)[t]++;if(hit)(shared?sharedRight:freeRight)[t]++;}boolean pass=o.confidence>=(shared?Lector.SHARED_CONFIDENCE:Lector.FREE_CONFIDENCE);if(pass){gateShown++;if(hit)gateRight++;passed=true;passedRight=hit;}}if(hit){neural++;row[1]++;}else if(found!=null)shownWrong++;tokens+=m.encode(ctx,1000).size();
   JSONArray rows=new JSONArray().put(new JSONObject().put("id","x").put("title","t").put("source","https://example.com").put("origin","web").put("saved",1L).put("truncated",false).put("text",ctx));String old=ReadingKnowledge.answer(rows,q);if(old==null){lexicalSilent++;if(passed){fallbackShown++;if(passedRight)fallbackRight++;}}if(old!=null){lexicalAnswered++;int start=old.indexOf('«'),end=old.indexOf("»\nFuente: ");String quote=start>=0&&end>start?flat(old.substring(start+1,end)):"";String t=flat(target);if(!quote.isEmpty()&&(t.contains(quote)&&quote.length()>=t.length()*2/3||quote.contains(t)&&quote.length()<=t.length()*3/2+40)){lexical++;row[2]++;}}}
  JSONObject kinds=new JSONObject();for(Map.Entry<String,int[]> k:by.entrySet())kinds.put(k.getKey(),new JSONObject().put("examples",k.getValue()[0]).put("reader",k.getValue()[1]).put("lexical",k.getValue()[2]));
  JSONObject out=new JSONObject().put("examples",n).put("readerExactSentence",neural).put("readerShownButOtherSentence",shownWrong).put("readerNothingShown",n-neural-shownWrong).put("lexicalAnswered",lexicalAnswered).put("lexicalSameSentence",lexical).put("byKind",kinds).put("lexicalSilent",lexicalSilent).put("fallbackShownWhenLexicalSilent",fallbackShown).put("fallbackRightWhenLexicalSilent",fallbackRight).put("appGateShown",gateShown).put("appGateRight",gateRight).put("confidenceLevels",new JSONArray(LEVELS)).put("sharedWordShown",new JSONArray(sharedShown)).put("sharedWordRight",new JSONArray(sharedRight)).put("noSharedWordShown",new JSONArray(freeShown)).put("noSharedWordRight",new JSONArray(freeRight)).put("secondsPerExampleHostJvm",(System.nanoTime()-time)/1e9/Math.max(1,n)).put("meanFragmentTokens",tokens/Math.max(1,n)).put("note","Ejemplos generados con las plantillas de entrenamiento sobre artículos no vistos; el extractor léxico se mide sobre el mismo fragmento único. No es un benchmark externo.");
  Files.write(Paths.get(a[2]),out.toString(1).getBytes("UTF-8"));System.out.println(out.toString(1));}
}
